// Package vibe is the repository root. Its only job is to embed the licence files so the
// binaries can show them (Studio's Settings > About) without reading from disk.
package vibe

import _ "embed"

// License is the Apache-2.0 text of LICENSE.
//
//go:embed LICENSE
var License string

// Notice is NOTICE.
//
//go:embed NOTICE
var Notice string

// ThirdPartyNotices is THIRD_PARTY_NOTICES.md, generated by `task notices`.
//
//go:embed THIRD_PARTY_NOTICES.md
var ThirdPartyNotices string
